package identity

import (
	_ "embed"
	"strconv"
	"strings"
	"sync"

	"golang.org/x/text/unicode/norm"
)

// confusablesTSV is the UTS #39 MA table, generated by scripts/gen_confusables.py from a pinned Unicode file.
//
//go:embed confusables.tsv
var confusablesTSV string

var (
	confusablesOnce sync.Once
	confusables     map[rune][]rune
)

func loadConfusables() {
	confusables = make(map[rune][]rune, 7000)
	for _, line := range strings.Split(confusablesTSV, "\n") {
		if line == "" || line[0] == '#' {
			continue
		}
		src, dst, ok := strings.Cut(line, "\t")
		if !ok {
			continue
		}
		from, err := strconv.ParseUint(src, 16, 32)
		if err != nil {
			continue
		}
		var to []rune
		for _, h := range strings.Fields(dst) {
			r, err := strconv.ParseUint(h, 16, 32)
			if err != nil {
				to = nil
				break
			}
			to = append(to, rune(r))
		}
		if to != nil {
			confusables[rune(from)] = to
		}
	}
}

// Skeleton is the UTS #39 skeleton of s, lowercased: two strings that look alike have the same one
// (design I-3). "devtooI" with a capital i and "Devtool" both come out as "devtool".
func Skeleton(s string) string {
	confusablesOnce.Do(loadConfusables)
	var b strings.Builder
	for _, r := range norm.NFD.String(s) {
		if to, ok := confusables[r]; ok {
			b.WriteString(string(to))
		} else {
			b.WriteRune(r)
		}
	}
	return strings.ToLower(norm.NFD.String(b.String()))
}
